<?php use backend\models\StudentSemesterStatus as Status;use common\widgets\Alert;use yii\helpers\{Html,Url};$this->title='Status Semester';?>
<?=Alert::widget()?><div class="d-flex align-items-baseline mb-3"><h1 class="mb-0 mr-2">Status Semester</h1><span class="text-muted">Status Semester Mahasiswa Per Prodi</span></div><div class="card card-warning card-outline"><div class="card-body"><?=Html::beginForm(['index'],'get',['id'=>'semester-status-filter'])?><div class="row align-items-center"><div class="col-md-2 text-warning font-weight-bold">Periode</div><div class="col-md-5"><?=Html::dropDownList('academic_period',$academic_period,$periods,['class'=>'form-control'])?></div></div><?=Html::endForm()?></div></div><div class="card card-success card-outline"><div class="card-body"><div class="text-right mb-2"><?=Html::button('<i class="fas fa-check"></i> Buat Status Semester',['class'=>'btn btn-success','id'=>'generate-status'])?> <?=Html::a('<i class="fas fa-list"></i> Kelola Data',['list','academic_period'=>$academic_period],['class'=>'btn btn-primary'])?></div><table class="table table-bordered table-striped"><thead class="thead-dark"><tr><th rowspan="2" class="align-middle text-center">Program Studi</th><th colspan="3" class="text-center">Jumlah Mahasiswa</th></tr><tr><th class="text-center">Aktif</th><th class="text-center">Cuti</th><th class="text-center">Non Aktif</th></tr></thead><tbody><tr class="font-weight-bold"><td>Seluruh Universitas</td><td class="text-right"><?=$total[Status::STATUS_ACTIVE]?></td><td class="text-right"><?=$total[Status::STATUS_LEAVE]?></td><td class="text-right"><?=$total[Status::STATUS_INACTIVE]?></td></tr><?php $facultyId=null;$facultyRows=[];foreach($programs as $program)$facultyRows[$program->faculty_id][]=$program;foreach($facultyRows as $fid=>$facultyPrograms):$faculty=$facultyPrograms[0]->faculty;$facultyTotal=[Status::STATUS_ACTIVE=>0,Status::STATUS_LEAVE=>0,Status::STATUS_INACTIVE=>0];foreach($facultyPrograms as $p)foreach($facultyTotal as $s=>$_)$facultyTotal[$s]+=$summary[$p->id][$s]??0;?><tr class="font-weight-bold bg-light"><td class="pl-4"><?=Html::encode($faculty->unit_name??'Tanpa Fakultas')?></td><td class="text-right"><?=$facultyTotal[Status::STATUS_ACTIVE]?></td><td class="text-right"><?=$facultyTotal[Status::STATUS_LEAVE]?></td><td class="text-right"><?=$facultyTotal[Status::STATUS_INACTIVE]?></td></tr><?php foreach($facultyPrograms as $program):?><tr><td class="pl-5"><?=Html::a(Html::encode($program->program_type.' - '.$program->name),['list','academic_period'=>$academic_period,'study_program_id'=>$program->id])?></td><td class="text-right"><?=$summary[$program->id][Status::STATUS_ACTIVE]??0?></td><td class="text-right"><?=$summary[$program->id][Status::STATUS_LEAVE]??0?></td><td class="text-right"><?=$summary[$program->id][Status::STATUS_INACTIVE]??0?></td></tr><?php endforeach;endforeach?></tbody></table><div class="mt-3 small"><?php foreach(Status::statusDescriptions() as $status=>$description):?><div><strong><?=Status::statusOptions()[$status]?>:</strong> <?=Html::encode($description)?></div><?php endforeach?></div></div></div>
<?php $url=Url::to(['generate','academic_period'=>$academic_period]);$js=<<<'JS'
$('#semester-status-filter select').on('change',function(){$('#semester-status-filter').submit();});
$('#generate-status').on('click',function(){Swal.fire({title:'Buat Status Semester?',text:'Status mahasiswa yang belum tersedia akan dibuat untuk periode ini.',icon:'question',showCancelButton:true,confirmButtonText:'Ya, Buat',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;$.post('__GENERATE_URL__',{_csrf:yii.getCsrfToken()}).done(function(x){Swal.fire('Berhasil',x.message,'success').then(function(){location.reload();});});});});
JS;$this->registerJs(str_replace('__GENERATE_URL__',$url,$js));?>
